static void dm_DsTproverkau2eShablon_put(dm_DsTproverkau2eShablon *d, dan_str k, dt_proverkau2eShablon v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsTproverkau2eShablon_lookup(d, k, h);
    if (e >= 0) { dt_proverkau2eShablon old = d->vals[e]; d->vals[e] = dt_proverkau2eShablon_share(v); dt_proverkau2eShablon_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsTproverkau2eShablon_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dt_proverkau2eShablon_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
