typedef struct { dan_str s; int64_t i; } dan_catp;
/* склейка до 16 частей: строка (s) или цифры целого (s == NULL) - одно выделение памяти */
static dan_str dan_cat(size_t n, const dan_catp *p) {
    char b[16][24];
    const char *q[16];
    size_t l[16], t = 0;
    for (size_t k = 0; k < n; k++) {
        if (p[k].s) { q[k] = p[k].s; l[k] = strlen(p[k].s); }
        else { q[k] = dan_itoa(p[k].i, b[k] + sizeof b[k]); l[k] = (size_t)(b[k] + sizeof b[k] - 1 - q[k]); }
        t += l[k];
    }
    char *r = dan_str_new(t), *w = r;
    for (size_t k = 0; k < n; k++) { memcpy(w, q[k], l[k]); w += l[k]; }
    return r;
}

/* соединение строк списка: длины считаются один раз, итог - одним выделением памяти */
static size_t dan_join_len(const dl_Ls *l, dan_str sep, size_t *lens, size_t *ls) {
    size_t s = strlen(sep), t = 0;
    for (int64_t i = 0; i < l->len; i++) {
        lens[i] = strlen(l->items[i]);
        if (lens[i] > SIZE_MAX / 2 - t || (i && s > SIZE_MAX / 2 - t - lens[i])) dan_error(DAN_MSG_NO_MEMORY, 0);
        t += lens[i] + (i ? s : 0);
    }
    *ls = s;
    return t;
}
static void dan_join_copy(const dl_Ls *l, dan_str sep, const size_t *lens, size_t s, char *w) {
    for (int64_t i = 0; i < l->len; i++) {
        if (i && s) { memcpy(w, sep, s); w += s; }
        if (lens[i]) { memcpy(w, l->items[i], lens[i]); w += lens[i]; }
    }
}
static dan_str dan_join(const dl_Ls *l, dan_str sep) {
    size_t small[64], s;
    size_t *lens = l->len <= 64 ? small : dan_alloc(sizeof(size_t) * (size_t)l->len);
    const size_t t = dan_join_len(l, sep, lens, &s);
    char *r = dan_str_new(t);
    dan_join_copy(l, sep, lens, s, r);
    r[t] = 0;
    if (lens != small) dan_free(lens);
    return r;
}
static dan_bytes dan_join_bytes(const dl_Ls *l, dan_str sep) {
    size_t small[64], s;
    size_t *lens = l->len <= 64 ? small : dan_alloc(sizeof(size_t) * (size_t)l->len);
    const size_t t = dan_join_len(l, sep, lens, &s);
    dan_bytes_s *b = dan_bytes_alloc((int64_t)t);
    dan_join_copy(l, sep, lens, s, (char *)b->data);
    if (lens != small) dan_free(lens);
    return b;
}

static dl_Ls *dan_упорядочить_по_3(const dl_Ls *l, df_5 f) {
    int64_t n = l->len;
    dl_Ls *r = dl_Ls_copy(l);
    int64_t *k = dan_alloc(sizeof(int64_t) * (size_t)(n ? n : 1));
    int64_t *ix = dan_alloc(sizeof(int64_t) * (size_t)(n ? n : 1)), *tmp = dan_alloc(sizeof(int64_t) * (size_t)(n ? n : 1));
    for (int64_t i = 0; i < n; i++) { k[i] = df_5_call(f, l->items[i]); ix[i] = i; }
    for (int64_t w = 1; w < n; w *= 2)
        for (int64_t lo = 0; lo < n; lo += 2 * w) {
            int64_t mid = lo + w < n ? lo + w : n, hi = lo + 2 * w < n ? lo + 2 * w : n, a = lo, b = mid, o = lo;
            while (a < mid || b < hi) {
                if (b >= hi) { tmp[o++] = ix[a++]; continue; }
                if (a >= mid) { tmp[o++] = ix[b++]; continue; }
                int64_t ka = k[ix[a]], kb = k[ix[b]];
                tmp[o++] = ((ka < kb ? -1 : ka > kb)) <= 0 ? ix[a++] : ix[b++];
            }
            for (int64_t i = lo; i < hi; i++) ix[i] = tmp[i];
        }
    for (int64_t i = 0; i < n; i++) r->items[i] = l->items[ix[i]];
    dan_free(k); dan_free(ix); dan_free(tmp);
    return r;
}
